#!/usr/bin/env bash
# One-time owner-authorized signing recovery, not an application update.
# Adds a two-hour SSH key forced to four fixed maintenance operations.
# Does not install a signing private key, change trust, or touch market history.
# Access is removed by cleanup or a systemd expiry timer.
set -euo pipefail
[[ "$(id -u)" == 0 ]] || { echo "Run with sudo bash."; exit 1; }
for cmd in python3 systemd-run visudo sshd; do command -v "$cmd" >/dev/null || { echo "Missing required command: $cmd"; exit 1; }; done
test -f /etc/arblens/release-access.json
test -f /opt/arblens-authority/release_authority.py
test -f /var/lib/arblens-authority/authority.sqlite3
id ubuntu >/dev/null
sshd -t
umask 077
python3 - <<'ARBLENS_RECOVERY_INSTALL_PY'
import base64, datetime, os, pathlib, pwd, shutil, subprocess
marker="arblens-signing-maintenance-20261128"
helper=pathlib.Path("/usr/local/lib/"+marker+".py")
sudoers=pathlib.Path("/etc/sudoers.d/"+marker)
authorized=pathlib.Path("/home/ubuntu/.ssh/authorized_keys")
backup=pathlib.Path("/var/backups/arblens-signing/access-"+datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%dT%H%M%SZ"))
backup.mkdir(mode=0o700,parents=True)
if authorized.exists(): shutil.copy2(authorized,backup/"authorized_keys")
if helper.exists(): shutil.copy2(helper,backup/"previous-helper.py")
if sudoers.exists(): shutil.copy2(sudoers,backup/"previous-sudoers")
helper.write_bytes(base64.b64decode(""))
helper.chmod(0o700)
rule="ubuntu ALL=(root) NOPASSWD: /usr/bin/python3 "+str(helper)+" *\n"
sudoers.write_text(rule)
sudoers.chmod(0o440)
subprocess.run(["visudo","-cf",str(sudoers)],check=True)
owner=pwd.getpwnam("ubuntu")
authorized.parent.mkdir(mode=0o700,parents=True,exist_ok=True)
os.chown(authorized.parent,owner.pw_uid,owner.pw_gid)
expiry=datetime.datetime.now(datetime.timezone.utc)+datetime.timedelta(hours=2)
force='sudo -n /usr/bin/python3 '+str(helper)+' "$SSH_ORIGINAL_COMMAND"'
entry='restrict,expiry-time="'+expiry.strftime("%Y%m%d%H%M%SZ")+'",command="'+force.replace('"','\\"')+'" ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIOsFFC+tgwtS/ZidSS6YAH2k0NHp0JX/aC6+FptjxFy1 arblens-signing-maintenance-20261128'
lines=authorized.read_text().splitlines() if authorized.exists() else []
lines=[line for line in lines if marker not in line]
authorized.write_text("\n".join(lines+[entry])+"\n")
authorized.chmod(0o600)
os.chown(authorized,owner.pw_uid,owner.pw_gid)
subprocess.run(["systemctl","stop","arblens-signing-maintenance-expire.timer"],capture_output=True)
subprocess.run(["systemctl","reset-failed","arblens-signing-maintenance-expire.service"],capture_output=True)
subprocess.run(["systemd-run","--quiet","--unit=arblens-signing-maintenance-expire","--on-active=2h",
                "/usr/bin/python3",str(helper),"cleanup"],check=True)
print("ArbLens recovery channel ready; expires in 2 hours.")
print("Only status/upload/migrate/cleanup are permitted. No signing key was installed on this server.")
print("No trust key, release version, or history database has been changed yet.")
print("Access configuration backup: "+str(backup))
ARBLENS_RECOVERY_INSTALL_PY
